package vn.rtr.aeris.journey33;
import android.app.Activity;import android.os.*;import android.content.*;import android.net.Uri;import android.webkit.*;import android.widget.Toast;import android.view.WindowManager;import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Offline hybrid engineering shell; zero network/device/vehicle permissions. */
public final class ShellActivity extends Activity {
 private static final String ORIGIN="https://native33.aeris.invalid",PAGE=ORIGIN+"/index.html";
 private WebView web;private DraftStore store;private boolean foreground=false,dead=false;private final Handler main=new Handler(Looper.getMainLooper());private final ThreadPoolExecutor io=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<Runnable>(1),new ThreadPoolExecutor.AbortPolicy());private byte[] exported;private ValueCallback<Uri[]> imported;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);try{store=new DraftStore(new File(getFilesDir(),"native33-drafts").toPath());}catch(Exception e){Toast.makeText(this,"Draft store chưa khả dụng; không xác nhận đã lưu",Toast.LENGTH_LONG).show();}
 WebView.setWebContentsDebuggingEnabled(true);web=new WebView(this);setContentView(web);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(false);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setJavaScriptCanOpenWindowsAutomatically(false);web.addJavascriptInterface(new Bridge(),"Native33Bridge");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest q){return !PAGE.equals(q.getUrl().toString());}@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest q){try{Uri u=q.getUrl();String p=u.getPath();if(!"GET".equals(q.getMethod())||!"https".equals(u.getScheme())||!"native33.aeris.invalid".equals(u.getHost())||u.getPort()!=-1||u.getQuery()!=null||u.getFragment()!=null||p==null||!p.matches("/(index.html|shell.css|shell.mjs|editor.mjs|journey.mjs|pins.mjs|vendor/(survey|compiler).mjs)"))return refused();String type=p.endsWith(".css")?"text/css":p.endsWith(".mjs")?"text/javascript":"text/html";Map<String,String> h=new HashMap<>();h.put("Content-Security-Policy","default-src 'self';connect-src 'none';object-src 'none';frame-src 'none';base-uri 'none'");h.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(type,"UTF-8",200,"OK",h,getAssets().open("editor"+p));}catch(Exception e){return refused();}}});web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){if(!foreground||dead)return false;if(imported!=null)imported.onReceiveValue(null);imported=c;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(i,31);return true;}catch(Exception e){imported=null;c.onReceiveValue(null);return false;}}});web.loadUrl(PAGE);}
 private WebResourceResponse refused(){return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",Collections.emptyMap(),new ByteArrayInputStream("Offline resource refused".getBytes(StandardCharsets.UTF_8)));}
 private boolean trusted(){return foreground&&!dead&&web!=null&&PAGE.equals(web.getUrl());}
 private void reply(String id,String raw){main.post(()->{if(!dead&&web!=null&&PAGE.equals(web.getUrl()))web.evaluateJavascript("window.native33Result("+JSONObject.quote(id)+","+JSONObject.quote(raw)+")",null);});}
 private String error(String message){return "{\"ok\":false,\"error\":"+JSONObject.quote(message)+"}";}
 public final class Bridge {@JavascriptInterface public void request(String id,String action,String expected,String body){if(id==null||!id.matches("[a-f0-9-]{36}")||body==null||body.getBytes(StandardCharsets.UTF_8).length>DraftStore.MAX_BODY)return;main.post(()->{if(!trusted()){reply(id,error("Inactive/foreign page; authority not restored"));return;}if("export".equals(action)){if(exported!=null){reply(id,error("Export picker already pending"));return;}try{JSONObject value=new JSONObject(body);String format=value.getString("format");if(!format.equals("aeris-native33-workspace"))throw new IOException("Export schema");exported=body.getBytes(StandardCharsets.UTF_8);Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,format+".json");startActivityForResult(i,30);reply(id,"{\"ok\":true,\"status\":\"PICKER_OPENED_NOT_WRITTEN\"}");}catch(Exception e){exported=null;reply(id,error("Export picker refused"));}return;}if(store==null||!Arrays.asList("save","load").contains(action)){reply(id,error("Storage unavailable/action refused"));return;}try{io.execute(()->{try{DraftStore target=store;DraftStore.Snapshot result;if(action.startsWith("save")){JSONObject value=new JSONObject(body);if(value.getInt("version")!=1||value.has("authority"))throw new IOException("Schema/version");if(!value.getString("format").equals("aeris-native33-workspace")||value.getBoolean("operational")||value.getBoolean("authorityRestorable"))throw new IOException("Workspace scope");result=target.save(expected,body.getBytes(StandardCharsets.UTF_8));}else result=target.load();reply(id,JournalMain.json(result,target.pending()));}catch(Exception e){reply(id,error("Storage refused: "+e.getMessage()));}});}catch(RejectedExecutionException e){reply(id,error("Storage queue full; not saved"));}});}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==31){ValueCallback<Uri[]> c=imported;imported=null;if(c!=null)c.onReceiveValue(result==RESULT_OK&&data!=null&&data.getData()!=null&&"content".equals(data.getData().getScheme())?new Uri[]{data.getData()}:null);return;}if(request!=30)return;byte[] bytes=exported;exported=null;if(result!=RESULT_OK||data==null||data.getData()==null||bytes==null)return;Uri u=data.getData();if(!"content".equals(u.getScheme()))return;try{io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(u,"wt")){if(out==null)throw new IOException("No provider output");out.write(bytes);out.flush();main.post(()->{if(!dead)Toast.makeText(this,"Đã ghi JSON; không phải bằng chứng flight thực",Toast.LENGTH_LONG).show();});}catch(Exception e){main.post(()->{if(!dead)Toast.makeText(this,"Xuất có thể thiếu; giữ lỗi, chưa công bố",Toast.LENGTH_LONG).show();});}});}catch(RejectedExecutionException e){Toast.makeText(this,"Queue đầy; chưa xuất",Toast.LENGTH_LONG).show();}}
 @Override protected void onResume(){super.onResume();foreground=true;if(web!=null){web.onResume();web.evaluateJavascript("window.native33Lifecycle && window.native33Lifecycle('resume')",null);}}
 @Override protected void onPause(){foreground=false;if(web!=null){web.evaluateJavascript("window.native33Lifecycle && window.native33Lifecycle('pause')",null);web.onPause();}super.onPause();}
 @Override protected void onDestroy(){dead=true;foreground=false;if(imported!=null){imported.onReceiveValue(null);imported=null;}exported=null;io.shutdown();if(web!=null){web.removeJavascriptInterface("Native33Bridge");web.destroy();web=null;}super.onDestroy();}
}
